async def act(page):
    """
    1) Try to dismiss any visible modal/popover by clicking likely close controls (accessible buttons).
    2) Perform a site search for the keyword 'diabetes' by navigating to the site's search results page (relative goto).
       (Using a relative goto to "/?s=diabetes" is a reliable, accessible way to trigger the site's search if the visible
       complementary search widget is not reachable.)
    3) Wait for the search results to render inside role="main", locate role="article" children, and click the
       bottom (last) result's first link. If there are no links inside the article, click the article element itself
       as a fallback. The click that navigates away is the final action.
    """
    import asyncio

    # 1) Defensive attempts to close a visible popup using accessible button roles/names.
    try:
        # Try common close button names first
        close_names = ["×", "✕", "Close", "close", "Dismiss", "Dismiss popup", "Close (Esc)"]
        closed = False
        for name in close_names:
            try:
                btns = page.get_by_role("button", name=name)
                if await btns.count() > 0:
                    await btns.nth(0).click()
                    await asyncio.sleep(0.35)
                    closed = True
                    break
            except Exception:
                # continue trying other names
                pass

        if not closed:
            # Iterate all buttons and try to find one whose accessible name or aria-label suggests closing
            all_buttons = page.get_by_role("button")
            total = 0
            try:
                total = await all_buttons.count()
            except Exception:
                total = 0

            for i in range(total):
                try:
                    lbl = None
                    try:
                        lbl = await all_buttons.nth(i).get_attribute("aria-label")
                    except Exception:
                        lbl = None
                    # also try inner_text if aria-label not present
                    text = ""
                    try:
                        text = (await all_buttons.nth(i).inner_text()).strip()
                    except Exception:
                        text = ""
                    combined = "".join([s for s in [lbl or "", text or ""]])
                    if combined and ("close" in combined.lower() or "×" in combined or "✕" in combined):
                        await all_buttons.nth(i).click()
                        await asyncio.sleep(0.35)
                        closed = True
                        break
                except Exception:
                    continue
    except Exception:
        # If anything goes wrong in dismissal attempts, continue to search step; the search may still work.
        pass

    # 2) Perform the search via a relative goto to the site's search-results URL for the term 'diabetes'.
    #    Many WordPress sites support the ?s= query parameter for search, so use that as a pragmatic, reliable approach.
    await page.goto("/?s=diabetes")

    # 3) Wait for results and click the bottom result.
    main = page.get_by_role("main")
    try:
        await main.wait_for(state="visible", timeout=8000)
    except Exception:
        # fallback if the role-based wait doesn't succeed in time
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    articles = main.get_by_role("article")
    try:
        count = await articles.count()
    except Exception:
        count = 0

    if count == 0:
        # If no articles are present, as a fallback try to locate article-like links in main and click the last link.
        try:
            links_in_main = main.get_by_role("link")
            link_count = await links_in_main.count()
            if link_count > 0:
                await links_in_main.nth(link_count - 1).click()
                return
        except Exception:
            return

    # Click the last article's first link if present, otherwise click the article itself.
    last_article = articles.nth(count - 1)
    links = last_article.get_by_role("link")
    try:
        link_count = await links.count()
    except Exception:
        link_count = 0

    if link_count > 0:
        await links.nth(0).click()
    else:
        await last_article.click()

